#!/usr/bin/env bash
#
# Derives the scaffold pieces that list interface versions from whatever buf
# generated, so no hand-maintained file names a version. Run it after
# `buf generate`:
#
#   .github/scripts/derive-scaffolds.sh
#
#   node     gen/node/src/<version>.ts, one barrel per generated version, and
#            gen/node/src/index.ts, which re-exports each as a namespace
#   haskell  the exposed-modules list in gen/haskell/utxorpc.cabal
#
# Rust needs nothing here: protoc-gen-prost-crate already derives lib.rs and
# the feature list from the generated code.
#
# Which versions get generated is decided upstream (generate.yml passes
# --exclude-path for UNSTABLE_VERSIONS in the stable channel), so this script
# behaves the same in both channels and adding a version needs no edits here.

set -euo pipefail

cd "$(dirname "$0")/../.."

fail() {
  echo "derive-scaffolds: $*" >&2
  exit 1
}

header="// @generated by .github/scripts/derive-scaffolds.sh from the buf output. Do not edit."

# ---------------------------------------------------------------------------
# node

node_src=gen/node/src
[[ -d $node_src/utxorpc ]] || fail "$node_src/utxorpc not found; run buf generate first"

versions=$(find "$node_src/utxorpc" -mindepth 1 -maxdepth 1 -type d -exec basename {} \; | LC_ALL=C sort)
[[ -n $versions ]] || fail "no generated versions under $node_src/utxorpc"

# Drop barrels from an earlier run, so a version no longer generated cannot
# linger in a reused working tree. Only files carrying this script's header
# are touched.
for old in "$node_src"/*.ts; do
  [[ -f $old && $(head -n 1 "$old") == "$header" ]] && rm "$old"
done

for version in $versions; do
  barrel=$node_src/$version.ts
  {
    echo "$header"
    # One namespace per proto file: `sync` for sync_pb, `syncConnect` for the
    # Connect service stubs next to it.
    (cd "$node_src" && find "utxorpc/$version" -name '*_pb.ts' | LC_ALL=C sort) | while read -r pb; do
      stem=$(basename "$pb" _pb.ts)
      echo "export * as $stem from \"./${pb%.ts}.js\";"
      connect=${pb%_pb.ts}_connect.ts
      if [[ -f $node_src/$connect ]]; then
        echo "export * as ${stem}Connect from \"./${connect%.ts}.js\";"
      fi
    done
  } > "$barrel"
  grep -q '^export' "$barrel" || fail "$barrel: no generated modules for $version"
  echo "derive-scaffolds: $barrel"
done

# The root re-export of v1alpha predates side-by-side versions and is part of
# the published API, so v1alpha must always be generated.
[[ " $(echo $versions) " == *" v1alpha "* ]] || fail "v1alpha was not generated; the root re-export needs it"

{
  echo "$header"
  for version in $versions; do
    echo "export * as $version from \"./$version.js\";"
  done
  echo
  echo "// Back-compat: before the interface held side-by-side versions, this package"
  echo "// re-exported v1alpha's modules at the root. Keep resolving them there so"
  echo "// existing \`spec.sync\` / \`spec.cardano\` callers are unaffected."
  echo "export * from \"./v1alpha.js\";"
} > "$node_src/index.ts"
echo "derive-scaffolds: $node_src/index.ts"

# ---------------------------------------------------------------------------
# haskell

cabal=gen/haskell/utxorpc.cabal
[[ -d gen/haskell/Proto ]] || fail "gen/haskell/Proto not found; run buf generate first"

modules=$(cd gen/haskell && find Proto -name '*.hs' | sed -e 's|\.hs$||' -e 's|/|.|g' | LC_ALL=C sort)
[[ -n $modules ]] || fail "no generated modules under gen/haskell/Proto"

grep -q '^  exposed-modules:$' "$cabal" || fail "$cabal: no '  exposed-modules:' line in the library stanza"

# Replace the field's body (module names or the committed placeholder comment)
# with the generated module list.
MODULES=$modules perl -0777 -pi -e '
  my $list = join "", map { "      $_\n" } split /\n/, $ENV{MODULES};
  s/^(  exposed-modules:\n)(?:[ \t]+(?:--.*|Proto\..*)\n)*/$1$list/m;
' "$cabal"
echo "derive-scaffolds: $cabal ($(echo "$modules" | wc -l | tr -d ' ') modules)"
